*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#050607;color:#eee;font-family:'DM Mono',monospace}body{user-select:none;-webkit-user-select:none}#game{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#080b0c}canvas#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.grain,.vignette{position:absolute;inset:0;pointer-events:none}.grain{z-index:2;opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E");mix-blend-mode:overlay}.vignette{z-index:2;background:radial-gradient(ellipse at center,transparent 30%,rgba(0,0,0,.4) 100%)}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:68px;padding:0 40px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff13;background:linear-gradient(#050708c9,transparent)}.brand{font:500 14px 'Oswald',sans-serif;letter-spacing:2px}.brand i{display:inline-block;width:7px;height:7px;background:#d04c31;border-radius:50%;margin:0 10px 1px 0;box-shadow:0 0 12px #e65338}.brand span{color:#697174;font-size:10px;margin-left:10px;letter-spacing:1.5px}.clock{font-size:10px;color:#8f9999;letter-spacing:1px}.clock b{font-weight:400;color:#d9d4c8;margin-left:12px}.pulse{display:inline-block;width:6px;height:6px;border-radius:50%;background:#c54a32;margin-right:8px;animation:blink 1.4s infinite}@keyframes blink{50%{opacity:.3}}.screen{position:absolute;z-index:4;inset:0;display:flex;align-items:center}.intro{background:linear-gradient(90deg,rgba(5,8,9,.97) 0%,rgba(5,8,9,.88) 35%,rgba(5,8,9,.32) 73%,rgba(5,8,9,.28) 100%)}.intro-copy{margin-left:11.5vw;margin-top:3vh;max-width:510px}.eyebrow{display:flex;align-items:center;gap:12px;color:#b25742;font-size:9px;letter-spacing:2.6px}.line{height:1px;width:28px;background:#a94936}.intro h1{font:600 clamp(78px,11vw,154px)/.77 'Oswald',sans-serif;letter-spacing:-3px;margin:29px 0 17px;color:#e9e6da}.intro h1 em{font-style:normal;color:#c84934}.subtitle{font:400 15px 'Oswald',sans-serif;letter-spacing:5px;color:#aab1ab;margin:25px 0 32px}.story{border-left:1px solid #b44d37;padding-left:17px;margin:0 0 30px}.story span{font-size:9px;letter-spacing:1.7px;color:#bc604a}.story p{font-size:11px;line-height:1.9;color:#a2a9a4;margin:9px 0 0}.primary{border:1px solid #b14835;color:#eee3d7;background:#ad3d2c;padding:0 18px;height:47px;min-width:224px;display:flex;align-items:center;justify-content:space-between;gap:30px;font:500 11px 'DM Mono';letter-spacing:1.2px;cursor:pointer;transition:.2s}.primary:hover{background:#d1523a;box-shadow:0 0 30px #b33a2b44}.primary b{font-size:16px;font-weight:400}.controls-copy{margin-top:43px;color:#ddd;font-size:9px;letter-spacing:1px}.controls-copy span{color:#6f7a79;margin-left:6px;margin-right:15px}.controls-copy i{display:inline-block;height:11px;width:1px;background:#3d4645;vertical-align:middle;margin-right:15px}.mobile-note{display:none;margin-top:18px;color:#6b7776;font-size:8px;letter-spacing:1.4px}.intro-stamp{position:absolute;right:9vw;bottom:11vh;border:1px solid #a34a393d;padding:15px 20px;color:#8c7268;font-size:9px;line-height:1.8;letter-spacing:2px;transform:rotate(-7deg);text-align:center}.intro-stamp b{color:#a84936;font-size:8px}.hud{position:absolute;z-index:3;inset:0;pointer-events:none}.objective{position:absolute;top:96px;left:40px;display:flex;flex-direction:column;gap:8px}.objective small,.power-top,.fear>span{font-size:8px;letter-spacing:1.8px;color:#899390}.objective strong{font:500 17px 'Oswald';letter-spacing:1.8px;color:#ece9df}.objective>span{font-size:10px;color:#9da6a0}.power{position:absolute;right:40px;top:94px;width:165px}.power-top{display:flex;justify-content:space-between;margin-bottom:10px}.power-top b{font-weight:400;color:#d4d7cc}.power-track{height:2px;background:#545e59}.power-track i{display:block;width:0;height:100%;background:#c85338;transition:width .5s;box-shadow:0 0 10px #d45135}.fear{position:absolute;bottom:34px;left:40px}.fear-bars{display:flex;gap:4px;margin-top:9px}.fear-bars i{width:20px;height:3px;background:#8e3c30;transition:.3s}.fear-bars i.off{background:#39413e}.crosshair{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:18px;height:18px;display:flex;align-items:center;justify-content:center;gap:3px;opacity:.75}.crosshair i{width:2px;height:2px;background:#d8d6ca}.crosshair b{width:2px;height:2px;background:#d8d6ca}.prompt{position:absolute;top:59%;left:50%;transform:translateX(-50%);font-size:9px;letter-spacing:1.4px;color:#ddd;display:flex;align-items:center;gap:10px}.prompt kbd{border:1px solid #b7c0b9;padding:5px 8px;font:10px 'DM Mono'}.hint{position:absolute;bottom:70px;left:50%;transform:translateX(-50%);color:#e1c4a4;font-size:10px;letter-spacing:1px;text-shadow:0 2px 6px black;white-space:nowrap}.ending{background:rgba(3,5,6,.83);flex-direction:column;justify-content:center;text-align:center}.ending .eyebrow{margin-bottom:20px}.ending h2{font:500 clamp(38px,8vw,82px) 'Oswald';letter-spacing:3px;margin:0;color:#e6e2d5}.ending p{max-width:440px;font-size:12px;line-height:1.9;color:#a6aeaa;margin:22px 24px 30px}.ending .primary{justify-content:center}.audio-toggle{position:absolute;z-index:4;right:25px;bottom:20px;color:#b5bdb5;font-size:14px;cursor:pointer;letter-spacing:1px}.audio-toggle span{font-size:8px;color:#7e8984;vertical-align:2px;margin-left:4px}.flashlight{position:absolute;z-index:1;pointer-events:none;inset:0;background:radial-gradient(ellipse 32% 40% at 50% 50%,transparent 0%,rgba(2,4,5,.18) 68%,rgba(0,0,0,.7) 100%);mix-blend-mode:multiply;opacity:0}.mobile-controls{display:none}.landscape{display:none}.rotate-icon{font-size:44px;color:#c34b35;animation:turn 2s infinite}@keyframes turn{50%{transform:rotate(90deg)}}
@media(max-width:700px){.topbar{height:48px;padding:0 18px}.brand{font-size:11px}.brand span{font-size:8px}.clock{font-size:8px}.intro-copy{margin:0 8vw;max-width:400px}.intro h1{font-size:clamp(74px,18vw,120px)}.intro-stamp{right:6vw;bottom:7vh;scale:.8}.controls-copy{display:none}.mobile-note{display:block}.story p{font-size:10px}.objective{top:62px;left:20px}.power{top:65px;right:20px;width:110px}.objective strong{font-size:14px}.objective>span{font-size:9px}.fear{bottom:22px;left:20px}.audio-toggle{bottom:15px;right:14px}.mobile-controls{display:block;position:absolute;inset:0;pointer-events:none}.stick{pointer-events:auto;position:absolute;bottom:25px;left:22px;width:108px;height:108px;border-radius:50%;border:1px solid #e1e9df44;background:#141b19a8;touch-action:none}.stick:before{content:'';position:absolute;inset:23px;border:1px solid #e1e9df22;border-radius:50%}.stick i{position:absolute;width:37px;height:37px;left:35px;top:35px;border-radius:50%;background:#b4c0b247;border:1px solid #d6dfd355}.action-btn,.flash-btn{pointer-events:auto;position:absolute;right:25px;border:1px solid #d2dfd455;border-radius:50%;background:#1b2220b8;color:#eee;font:10px 'DM Mono';letter-spacing:1px;touch-action:none}.action-btn{bottom:42px;width:66px;height:66px}.flash-btn{bottom:122px;width:56px;height:56px;font-size:8px}.flash-btn span{display:block;font-size:17px}.prompt{display:none}.landscape{position:absolute;z-index:10;inset:0;background:#080b0b;align-items:center;justify-content:center;flex-direction:column;gap:15px;text-align:center;color:#ddd;font-size:12px;letter-spacing:2px}.landscape small{font-size:8px;color:#89928c}.hud[hidden],.screen[hidden]{display:none!important}}
@media(max-width:700px) and (orientation:portrait){.landscape{display:flex}.intro,.ending{visibility:hidden}.topbar{visibility:hidden}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#scene'), hud=document.querySelector('#hud'), intro=document.querySelector('#intro'), ending=document.querySelector('#ending');
const mobile=matchMedia('(pointer:coarse)').matches;
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x080d10); scene.fog=new THREE.FogExp2(0x080d10,.047);
const camera=new THREE.PerspectiveCamera(72,innerWidth/innerHeight,.08,70); camera.position.set(0,1.7,8);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.1;
scene.add(new THREE.HemisphereLight(0x80969b,0x151716,.21));
const mat=(color,roughness=.8,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const concrete=mat(0x303638), floorMat=mat(0x252a29), ceilingMat=mat(0x202728), deskMat=mat(0x463c32), metal=mat(0x384346,.45,.6), glass= new THREE.MeshStandardMaterial({color:0x101b20,roughness:.2,metalness:.4,emissive:0x0b141a}), paper=mat(0xb9b5a4), black=mat(0x101414,.4,.2);
function box(x,y,z,w,h,d,m,cast=true){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=cast;o.receiveShadow=true;scene.add(o);return o}
// sealed, dim office
box(0,-.16,-5,24,.32,36,floorMat);box(0,6,-5,24,.25,36,ceilingMat,false);
box(-12,3,-5,.35,6,36,concrete);box(12,3,-5,.35,6,36,concrete);box(0,3,-23,24,6,.35,concrete);box(0,3,13,24,6,.35,concrete);
// worn tile seams and wall trim
for(let x=-10;x<=10;x+=2)box(x,.015,-5,.018,.012,35,mat(0x343a38),false);
for(let z=-22;z<=12;z+=2)box(0,.016,z,23,.012,.018,mat(0x343a38),false);
for(const side of [-1,1]){box(side*11.78,.45,-5,.1,.9,35,metal,false);for(let z=-19;z<12;z+=5){box(side*11.78,3.8,z,.08,2.1,3.7,glass,false);box(side*11.72,3.8,z,.1,.08,3.8,metal,false);box(side*11.72,3.8,z,.1,2.2,.08,metal,false)}}
// office rows: desks, screens, scattered paperwork, chairs
for(let row=0;row<5;row++){const z=8-row*6.4;for(const x of [-7,-2.3,2.3,7]){if(row===0&&Math.abs(x)<3)continue;box(x,.9,z,3.1,.16,1.55,deskMat);for(const dx of [-1.35,1.35])for(const dz of [-.62,.62])box(x+dx,.43,z+dz,.09,.9,.09,metal);box(x,.9,z-.38,.09,.05,.04,metal,false);
const mon=box(x,.3+1.15,z-.35,1.02,.73,.11,black);mon.position.y=1.45;box(x,1.45,z-.285,.84,.53,.012,mat(0x111d1d,.2,.1),false);
const glow=new THREE.Mesh(new THREE.PlaneGeometry(.76,.44),new THREE.MeshBasicMaterial({color:0x16483d}));glow.position.set(x,1.45,z-.276);scene.add(glow);
box(x+.5,1.01,z+.33,.72,.035,.43,paper,false);const chair=new THREE.Group();chair.position.set(x,0,z+1.55);chair.add(new THREE.Mesh(new THREE.BoxGeometry(.8,.17,.75),mat(0x202b2a)));chair.children[0].position.y=.55;const back=new THREE.Mesh(new THREE.BoxGeometry(.8,.9,.12),mat(0x202b2a));back.position.set(0,1,-.28);chair.add(back);scene.add(chair);
}}
// old file cabinets, water cooler and printer dressing
for(const x of [-10.2,10.2]){for(const z of [-18,-14,8]){box(x,.9,z,1.05,1.8,1.1,metal);for(let y=.45;y<1.6;y+=.48){box(x,y,z-.57,.85,.025,.02,black,false);box(x,y+.12,z-.61,.16,.03,.04,mat(0x88908a),false)}}}
box(-9,.65,-20,1.1,1.3,1,black);box(-9,1.36,-20,.9,.12,.8,metal);box(9,1.2,10,.65,2.4,.65,glass);box(9,2.5,10,.8,.15,.8,metal);
// ceiling fluorescent fixtures, each with a sabotaged electrical pulse
const fixtures=[];for(let z=9;z>=-20;z-=5){for(const x of [-7,0,7]){box(x,5.82,z,2.7,.08,.42,mat(0x555c57),false);const panel=new THREE.Mesh(new THREE.BoxGeometry(2.42,.035,.28),new THREE.MeshBasicMaterial({color:0xb8d4c6}));panel.position.set(x,5.75,z);scene.add(panel);const light=new THREE.PointLight(0xa6c8bb, rowPower(),11,2);light.position.set(x,5.35,z);light.castShadow=(x===0&&z===-5);scene.add(light);fixtures.push({light,panel,base:light.intensity})}}
function rowPower(){return .3+Math.random()*.15}
// exit door and emergency sign
box(0,2.1,-22.72,2.4,4.2,.18,mat(0x17201e));box(0,3.7,-22.58,1.15,.22,.07,mat(0x6f2923));const exitLabel=new THREE.Mesh(new THREE.PlaneGeometry(1.05,.17),new THREE.MeshBasicMaterial({color:0x9c392b}));exitLabel.position.set(0,3.7,-22.47);scene.add(exitLabel);
// portable flashlight spotlight, carried on camera
const torch=new THREE.SpotLight(0xdce9d5,26,23,Math.PI/7,.48,1.5);camera.add(torch);torch.position.set(.13,-.12,-.1);torch.target.position.set(0,0,-1);camera.add(torch.target);scene.add(camera);const glow=new THREE.PointLight(0xc9d9c8,1.4,4);camera.add(glow);glow.position.set(0,0,0);
// fuse pickups, isolated red beacons in the dark
const fusePositions=[new THREE.Vector3(-9,.5,2),new THREE.Vector3(8,.5,-9),new THREE.Vector3(-4,.5,-19)];const fuses=[];
for(let i=0;i<3;i++){const g=new THREE.Group();g.position.copy(fusePositions[i]);const cube=new THREE.Mesh(new THREE.BoxGeometry(.32,.54,.22),mat(0x9f4333,.4,.3));cube.castShadow=true;g.add(cube);const stripe=new THREE.Mesh(new THREE.BoxGeometry(.36,.09,.24),new THREE.MeshBasicMaterial({color:0xff9a62}));stripe.position.y=.07;g.add(stripe);const lamp=new THREE.PointLight(0xdb5534,1.5,4);lamp.position.y=.65;g.add(lamp);const ring=new THREE.Mesh(new THREE.TorusGeometry(.39,.012,5,24),new THREE.MeshBasicMaterial({color:0xc95138,transparent:true,opacity:.65}));ring.rotation.x=Math.PI/2;ring.position.y=-.12;g.add(ring);scene.add(g);fuses.push({group:g,got:false,ring})}
// something that should not be here. Long-limbed silhouette assembled from primitive geometry.
const stalker=new THREE.Group();stalker.visible=false;const shadowMat=new THREE.MeshStandardMaterial({color:0x080b0c,roughness:1});
function limb(parent,x,y,z,w,h,d,rot=0){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),shadowMat);m.position.set(x,y,z);m.rotation.z=rot;m.castShadow=true;parent.add(m);return m}
limb(stalker,0,1.55,0,.49,.95,.34);limb(stalker,0,2.35,.02,.38,.48,.34);limb(stalker,-.1,2.38,-.16,.09,.08,.03);limb(stalker,.1,2.38,-.16,.09,.08,.03);limb(stalker,-.39,1.25,0,.16,1.65,.17,-.12);limb(stalker,.39,1.25,0,.16,1.65,.17,.12);limb(stalker,-.14,.42,0,.2,.95,.22,.04);limb(stalker,.14,.42,0,.2,.95,.22,-.04);scene.add(stalker);
const redEyes=new THREE.Group();for(const x of [-.1,.1]){const e=new THREE.Mesh(new THREE.SphereGeometry(.032,8,8),new THREE.MeshBasicMaterial({color:0xd43b2c}));e.position.set(x,2.39,-.18);redEyes.add(e)}stalker.add(redEyes);
// gameplay state
let started=false, ended=false, powered=false, count=0, angle=0, pitch=0, flashlightOn=true, soundOn=true, fear=100, last=performance.now(), elapsed=0, interactTarget=null, audioCtx=null, heartbeatTimer=0, voiceEnabled=true;
const keys={};const player={speed:4.15};const timeEl=document.querySelector('#time'),prompt=document.querySelector('#prompt'),hint=document.querySelector('#hint'),objective=document.querySelector('#objective'),sub=document.querySelector('#objective-sub');
function say(text){if(!voiceEnabled||!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=.88;u.pitch=.65;u.volume=.85;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>/en/i.test(v.lang)&&/female|samantha|aria|zira/i.test(v.name))||voices.find(v=>/en/i.test(v.lang))||null;speechSynthesis.speak(u)}
function audioStart(){if(!soundOn)return;try{audioCtx=new (window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sawtooth';osc.frequency.value=43;gain.gain.value=.018;osc.connect(gain);gain.connect(audioCtx.destination);osc.start()}catch(e){}}
function beep(freq=130,dur=.17){if(!audioCtx||!soundOn)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.12,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}
function start(){if(started)return;started=true;intro.hidden=true;hud.hidden=false;audioStart();if(!mobile&&canvas.requestPointerLock)canvas.requestPointerLock();say('You are the last one in the office. Find the three fuses. And whatever you hear... do not follow it.');setTimeout(()=>{if(started&&!ended){say('Did you hear that?');hint.textContent='A sound echoes from somewhere down the hall.';setTimeout(()=>hint.textContent='',4000)}},13000)}
document.querySelector('#start-btn').onclick=start;
document.querySelector('#restart-btn').onclick=()=>location.reload();
document.querySelector('#audio-toggle').onclick=()=>{soundOn=!soundOn;document.querySelector('#audio-toggle').innerHTML=`${soundOn?'♫':'♩'} <span>SOUND ${soundOn?'ON':'OFF'}</span>`;if(soundOn&&!audioCtx)audioStart();if(audioCtx&&!soundOn)audioCtx.suspend();else if(audioCtx)audioCtx.resume()};
function interact(){if(!started||ended)return;if(interactTarget?.type==='fuse'){const f=interactTarget.f;f.got=true;scene.remove(f.group);count++;document.querySelector('#fuses').textContent=`${count} / 3`;document.querySelector('#power-fill').style.width=`${count*33.33}%`;beep(540,.25);hint.textContent=['The fuse is cold. Colder than it should be.','Somewhere nearby, something shifts.','The lights are waiting. So is it.'][count-1];say(['One fuse. Keep moving.','Two. It knows you are here.','That is all of them. Get to the electrical panel.'][count-1]);setTimeout(()=>hint.textContent='',4000);if(count===3){objective.textContent='RESTORE THE POWER';sub.textContent='Reach the electrical panel at the far end.';}}
else if(interactTarget?.type==='exit'){if(count<3){hint.textContent='The emergency exit is locked. The power must be restored.';beep(90,.3);setTimeout(()=>hint.textContent='',2500)}else{powered=true;fixtures.forEach(f=>{f.light.intensity=.8;f.panel.material.color.setHex(0xc0e7ce)});document.querySelector('#power-fill').style.width='100%';objective.textContent='GET OUT';sub.textContent='The exit is at the far end of the office.';beep(680,.4);say('Power restored. The emergency exit is open. Run.');hint.textContent='THE EXIT IS OPEN. MOVE!';setTimeout(()=>hint.textContent='',3500)}}
else if(interactTarget?.type==='door'&&powered){endGame(true)}
}
window.addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='KeyE'||e.code==='Enter')interact();if(e.code==='KeyF')toggleFlash();if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault()});window.addEventListener('keyup',e=>keys[e.code]=false);
function toggleFlash(){flashlightOn=!flashlightOn;torch.intensity=flashlightOn?26:0;glow.intensity=flashlightOn?1.4:0;document.querySelector('#flash-btn').style.opacity=flashlightOn?'1':'.45';beep(flashlightOn?370:190,.08)}document.querySelector('#flash-btn').onclick=toggleFlash;document.querySelector('#interact-btn').onclick=interact;
canvas.addEventListener('click',()=>{if(started&&!mobile&&document.pointerLockElement!==canvas)canvas.requestPointerLock()});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas){angle-=e.movementX*.0022;pitch=Math.max(-.55,Math.min(.55,pitch-e.movementY*.0018))}});
let touchLook=null;const lookPad=document.querySelector('#look-pad');lookPad.addEventListener('pointerdown',e=>{touchLook={x:e.clientX,y:e.clientY};lookPad.setPointerCapture(e.pointerId)});lookPad.addEventListener('pointermove',e=>{if(!touchLook)return;angle-=(e.clientX-touchLook.x)*.006;pitch=Math.max(-.5,Math.min(.5,pitch-(e.clientY-touchLook.y)*.005));touchLook={x:e.clientX,y:e.clientY}});lookPad.addEventListener('pointerup',()=>touchLook=null);
let stickInput={x:0,y:0};const stick=document.querySelector('#stick');stick.addEventListener('pointerdown',e=>{stick.setPointerCapture(e.pointerId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.buttons)moveStick(e)});stick.addEventListener('pointerup',()=>{stickInput={x:0,y:0};stick.children[0].style.transform='translate(0,0)'});function moveStick(e){const r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),scale=Math.min(1,42/len);stickInput={x:dx/42*scale,y:dy/42*scale};stick.children[0].style.transform=`translate(${stickInput.x*28}px,${stickInput.y*28}px)`}
function endGame(win){if(ended)return;ended=true;document.exitPointerLock?.();ending.hidden=false;document.querySelector('#end-title').textContent=win?'THE LIGHTS ARE BACK.':'IT FOUND YOU.';document.querySelector('#end-copy').textContent=win?'You made it outside. Behind you, one by one, the office lights go dark again. Your shift is over. For now.':'The last thing you see is the emergency light going out. Incident log closed. Employee 0841: unaccounted for.';say(win?'You made it outside. Your shift is over.':'No. No, please.');}
function update(dt,t){if(!started||ended)return;elapsed+=dt;const mins=17+Math.floor(elapsed*1.25);timeEl.textContent=`02:${String(mins%60).padStart(2,'0')} AM`;
// Move in the camera-relative plane; confinement to room boundaries
